WITH flattened AS (SELECT id, service, host, latency_ms, key, v FROM app_logs LATERAL VIEW EXPLODE(context) li AS key, v) SELECT id, service, host, latency_ms, key, v, ROW_NUMBER() OVER w_recent AS event_seq, LEAD(latency_ms, 2) OVER (PARTITION BY key ORDER BY latency_ms, id, key) AS next_latency_ms, SUM(latency_ms) OVER (PARTITION BY key ORDER BY latency_ms, id, key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_latency_ms FROM flattened WINDOW w_recent AS (PARTITION BY key ORDER BY latency_ms DESC, id, key);
